  <script id="zp-suite-front-fixes-229-faq-mega-final-js">
    (function(){
      function fixFaqMega(){
        if(!document.body || !document.body.classList.contains('zp-faq-nav-as-realizacje')) return;
        var nav=document.getElementById('zpNewNav');
        if(nav){
          var light=nav.querySelectorAll('.zpNewNav__logo--light,.zpNewNav__mobileLogo--light');
          var dark=nav.querySelectorAll('.zpNewNav__logo--dark,.zpNewNav__mobileLogo--dark');
          if(nav.classList.contains('is-mega-open')){
            light.forEach(function(el){el.style.setProperty('display','none','important');el.style.setProperty('opacity','0','important');el.style.setProperty('visibility','hidden','important');});
            dark.forEach(function(el){el.style.setProperty('display','block','important');el.style.setProperty('opacity','1','important');el.style.setProperty('visibility','visible','important');});
          }
        }
        document.querySelectorAll('body > .zpNewNav__mega.zpNewNav__mega--portal .zpNewNav__megaHead, body > .zpNewNav__mega.zpNewNav__mega--portal .zpNewNav__megaTitle, body > .zpNewNav__mega.zpNewNav__mega--portal .zpNewNav__megaLink').forEach(function(el){
          el.style.setProperty('color','#07101e','important');
          el.style.setProperty('opacity','1','important');
        });
        document.querySelectorAll('body > .zpNewNav__mega.zpNewNav__mega--portal .zpNewNav__megaDesc').forEach(function(el){
          el.style.setProperty('color','#667085','important');
          el.style.setProperty('opacity','1','important');
        });
      }
      fixFaqMega();
      document.addEventListener('mouseover', fixFaqMega, true);
      document.addEventListener('click', function(){setTimeout(fixFaqMega,30);setTimeout(fixFaqMega,180);}, true);
      window.addEventListener('load', fixFaqMega);
    })();
  </script>
